#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>
#include <zephyr/drivers/video.h>
#include <zephyr/sys/slist.h>
#include <errno.h>
#include <string.h>

LOG_MODULE_REGISTER(video_buffer, CONFIG_VIDEO_BUFFER_LOG_LEVEL);

#ifndef CONFIG_VIDEO_MAX_BUFFERS
#define CONFIG_VIDEO_MAX_BUFFERS 4
#endif

/* Internal buffer state flags */
#define VIDEO_BUF_INTERNAL_FLAG_FREE        BIT(0)
#define VIDEO_BUF_INTERNAL_FLAG_ALLOCATED   BIT(1)

struct video_buffer_internal {
    struct video_buffer vbuf;
    uint32_t internal_flags;
};

static struct video_buffer_internal video_buffers[CONFIG_VIDEO_MAX_BUFFERS];
static K_MUTEX_DEFINE(video_buffer_mutex);

static int video_buffer_module_init(void)
{
    for (int i = 0; i < CONFIG_VIDEO_MAX_BUFFERS; i++) {
        memset(&video_buffers[i].vbuf, 0, sizeof(struct video_buffer));
        video_buffers[i].internal_flags = VIDEO_BUF_INTERNAL_FLAG_FREE;
    }
    LOG_DBG("Video buffer pool initialized with %d buffers", CONFIG_VIDEO_MAX_BUFFERS);
    return 0;
}

SYS_INIT(video_buffer_module_init, APPLICATION, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);

struct video_buffer *video_buffer_alloc(size_t size)
{
    k_mutex_lock(&video_buffer_mutex, K_FOREVER);

    for (int i = 0; i < CONFIG_VIDEO_MAX_BUFFERS; i++) {
        if (video_buffers[i].internal_flags & VIDEO_BUF_INTERNAL_FLAG_FREE) {
            video_buffers[i].internal_flags &= ~VIDEO_BUF_INTERNAL_FLAG_FREE;
            video_buffers[i].internal_flags |= VIDEO_BUF_INTERNAL_FLAG_ALLOCATED;

            /* Initialize the public video_buffer structure */
            memset(&video_buffers[i].vbuf, 0, sizeof(struct video_buffer));
            video_buffers[i].vbuf.size = size;
            /* The actual buffer memory (vbuf.buffer) is expected to be set by the driver */

            LOG_DBG("Allocated buffer %d (ptr: %p)", i, &video_buffers[i].vbuf);
            k_mutex_unlock(&video_buffer_mutex);
            return &video_buffers[i].vbuf;
        }
    }

    k_mutex_unlock(&video_buffer_mutex);
    LOG_WRN("No free video buffers available");
    return NULL;
}

int video_buffer_release(struct video_buffer *vbuf)
{
    if (vbuf == NULL) {
        LOG_ERR("Attempted to release a NULL video buffer");
        return -EINVAL;
    }

    k_mutex_lock(&video_buffer_mutex, K_FOREVER);

    for (int i = 0; i < CONFIG_VIDEO_MAX_BUFFERS; i++) {
        if (&video_buffers[i].vbuf == vbuf) {
            if (video_buffers[i].internal_flags & VIDEO_BUF_INTERNAL_FLAG_FREE) {
                LOG_ERR("Buffer %d (%p) is already released", i, vbuf);
                k_mutex_unlock(&video_buffer_mutex);
                return -EALREADY;
            }

            video_buffers[i].internal_flags &= ~VIDEO_BUF_INTERNAL_FLAG_ALLOCATED;
            video_buffers[i].internal_flags |= VIDEO_BUF_INTERNAL_FLAG_FREE;

            /* Clear public video_buffer structure fields */
            memset(&video_buffers[i].vbuf, 0, sizeof(struct video_buffer));

            LOG_DBG("Released buffer %d (ptr: %p)", i, vbuf);
            k_mutex_unlock(&video_buffer_mutex);
            return 0;
        }
    }

    k_mutex_unlock(&video_buffer_mutex);
    LOG_ERR("Invalid video buffer pointer %p: not found in pool", vbuf);
    return -EINVAL;
}

/*
 * The error log also mentions "Invalid buffer index: 1".
 * This suggests there might be an index-based release function.
 * This function is not typically part of the public API, but might be used by tests.
 */
int video_buffer_release_idx(int index)
{
    if (index < 0 || index >= CONFIG_VIDEO_MAX_BUFFERS) {
        LOG_ERR("Invalid buffer index: %d (max: %d)", index, CONFIG_VIDEO_MAX_BUFFERS - 1);
        return -EINVAL;
    }
    return video_buffer_release(&video_buffers[index].vbuf);
}

/*
 * Helper to get a buffer by index, mainly for testing or internal use.
 * Not typically part of the public API, but useful for the test context.
 */
struct video_buffer *video_buffer_get_by_idx(int index)
{
    if (index < 0 || index >= CONFIG_VIDEO_MAX_BUFFERS) {
        LOG_ERR("Invalid buffer index: %d (max: %d)", index, CONFIG_VIDEO_MAX_BUFFERS - 1);
        return NULL;
    }
    return &video_buffers[index].vbuf;
}
